INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(12401, 'Job 21:34', 'Job', 21, 34, '&nbsp;نو بيا به تۀ ما له په تشو خبرو باندې څنګه تسلى راکړې؟ ستا هر يو جواب د دروغو نه ډک دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12402, 'Job 22:1', 'Job', 22, 1, '&nbsp;بيا تيمانى اليفز جواب ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12403, 'Job 22:2', 'Job', 22, 2, '&nbsp;”بنى آدم خُدائ پاک له څۀ فائده ورکولے شى؟ د ټولو نه هوښيار کس هم د هغۀ مدد کولے شى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12404, 'Job 22:3', 'Job', 22, 3, '&nbsp;د قادر خُدائ دپاره به څۀ خوشحالى وى کۀ تۀ صادق شې، کۀ ته خپل عملونه صفا کړې نو هغۀ له به څۀ فائده ورکړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12405, 'Job 22:4', 'Job', 22, 4, '&nbsp;چې تۀ پرهيزګار يې نو ځکه هغه په تا اِلزام لګوى او ولې ستا خِلاف د عدالت نه کار اخلى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12406, 'Job 22:5', 'Job', 22, 5, '&nbsp;نه، هغه وجه ده چې ستا بدعملى زياته ده او ستا د ګناهونو ختمېدل نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12407, 'Job 22:6', 'Job', 22, 6, '&nbsp;لکه چې تا د خپلو وروڼو نه د قرض پېسې په زور اخستې دى، او تا د هغوئ نه جامې ويستې دى او بربنډ دې پرېښى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12408, 'Job 22:7', 'Job', 22, 7, '&nbsp;تا تږو کسانو له اوبۀ نۀ دى ورکړې، او تا د نهَرو کسانو نه روټۍ ايساره کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12409, 'Job 22:8', 'Job', 22, 8, '&nbsp;تا د خپل طاقت او حيثيت نه کار واخستلو او په ټول مُلک دې قبضه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12410, 'Job 22:9', 'Job', 22, 9, '&nbsp;تا کونډې تش لاس لېږلې دى، او يتيمان دې نااُميده کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12411, 'Job 22:10', 'Job', 22, 10, '&nbsp;نو په دې وجه ستا نه ګېرچاپېره دامونه دى، او يوه ناڅاپه يره به په تا باندې غالبه شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12412, 'Job 22:11', 'Job', 22, 11, '&nbsp;يا يوه داسې تيارۀ چې تۀ نور هيڅ نۀ شې ليدلے، د اوبو يو سېلاب به تا پټ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12413, 'Job 22:12', 'Job', 22, 12, '&nbsp;پاس په آسمانونو کښې خُدائ پاک نشته څۀ؟ پاس ستورى وګوره چې څومره اوچت دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12414, 'Job 22:13', 'Job', 22, 13, '&nbsp;نو دا ځکه تۀ وائې چې تۀ څۀ کوې نو خُدائ پاک ته پته نۀ لګى، هغه په توره وريځ کښې پټ دے نو هغه څنګه عدالت کولے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12415, 'Job 22:14', 'Job', 22, 14, '&nbsp;تکه توره وريځ د هغۀ نه تاو شى نو هغه کتل نۀ شى کولے، او هغه په عرش باندې مزل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12416, 'Job 22:15', 'Job', 22, 15, '&nbsp;تۀ به په هغه زړو لارو ځې څۀ، چې په کومو باندې بدعمله کسان تلل؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12417, 'Job 22:16', 'Job', 22, 16, '&nbsp;د هغوئ دوران راتلو نه مخکښې سېلاب هغوئ لاهو کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12418, 'Job 22:17', 'Job', 22, 17, '&nbsp;هغوئ خُدائ پاک ته وئيلى وُو چې زمونږ نه قلار شه، او داسې يقين يې لرلو چې قادر خُدائ د هغوئ هيڅ هم نۀ شى کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12419, 'Job 22:18', 'Job', 22, 18, '&nbsp;خو بيا هم هغه خُدائ پاک وو چې دوئ يې مالداره کړل، نو ځکه زۀ د بدعمله خلقو په خيالونو هيڅ غرض نۀ ساتم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12420, 'Job 22:19', 'Job', 22, 19, '&nbsp;صادقان د بدعمله تباهى ګورى او خوشحاليږى، خو بې‌ګناه کسان دوئ پورې خندا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12421, 'Job 22:20', 'Job', 22, 20, '&nbsp;وائى چې زمونږ دشمنان څنګه تباه شوى دى، او چې د هغوئ څۀ پاتې وُو هغه اور تباه کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12422, 'Job 22:21', 'Job', 22, 21, '&nbsp;خُدائ پاک ته خپل ځان حواله کړئ، او د هغۀ سره روغه وکړئ، او ستاسو هر کار به سم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12423, 'Job 22:22', 'Job', 22, 22, '&nbsp;د هغۀ په تعليماتو عمل کوئ، او د هغۀ خبرې زړۀ ته کوزې کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12424, 'Job 22:23', 'Job', 22, 23, '&nbsp;کۀ تاسو قادر خُدائ ته راواپس شئ، نو تاسو به په خپل ځائ باندې بيا ولګئ، کۀ تاسو د خپل ژوند نه بدى وباسئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12425, 'Job 22:24', 'Job', 22, 24, '&nbsp;کۀ تاسو سرۀ زر خاورې وګڼئ، او د اوفير سوچه سرۀ زر د سيند د کاڼو په شان وګڼئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12426, 'Job 22:25', 'Job', 22, 25, '&nbsp;نو بيا قادر خُدائ په خپله ستاسو د سرو زرو په شان دے او هغه ستاسو قيمتى سپين زر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12427, 'Job 22:26', 'Job', 22, 26, '&nbsp;نو بيا به تاسو د قادر خُدائ سره خوشحاله اوسئ، او د زړۀ نه به هغۀ سره ملاقات کولے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12428, 'Job 22:27', 'Job', 22, 27, '&nbsp;نو تاسو به هغۀ ته سوال وکړئ او هغه به ستاسو سوال قبول کړى، او تاسو به خپل قسمونه پوره کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12429, 'Job 22:28', 'Job', 22, 28, '&nbsp;تاسو به په هر کار کښې کامياب يئ، او ستاسو لار به روښانه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12430, 'Job 22:29', 'Job', 22, 29, '&nbsp;کله چې خُدائ پاک خلق کمزورى کړى نو تۀ وائې دا ځکه چې هغوئ مغروره وُو، خو په اصل کښې خُدائ پاک خلق په دې طريقې سره بچ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12431, 'Job 22:30', 'Job', 22, 30, '&nbsp;ځکه چې خُدائ پاک بې‌ګناه خلق بچ کوى، کۀ چرې تۀ بې‌ګناه يې نو هغه به تا هم بچ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12432, 'Job 23:1', 'Job', 23, 1, '&nbsp;بيا ايُوب جواب ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12433, 'Job 23:2', 'Job', 23, 2, '&nbsp;”زما شکايت په دې وخت کښې هم سخت دے، زۀ سلګۍ وهم او خُدائ پاک بيا هم ما له سزا راکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12434, 'Job 23:3', 'Job', 23, 3, '&nbsp;کاش چې ما هغه موندلے شوے، نو زۀ به د هغۀ دربار ته تلے وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12435, 'Job 23:4', 'Job', 23, 4, '&nbsp;زۀ به خپله مسئله هغۀ ته وړاندې کړم، او د هغۀ په حضور کښې به ټول عرضونه پېش کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12436, 'Job 23:5', 'Job', 23, 5, '&nbsp;چې هغه ما له څۀ جواب راکوى نو زۀ به ورته غوږ ونيسم، او چې څۀ راته وائى په هغې باندې به ځان پوهه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12437, 'Job 23:6', 'Job', 23, 6, '&nbsp;د دومره لوئ طاقت سره به هغه زما مخالفت کوى څۀ؟ خو نه داسې نۀ ده، هغه به زما خبره په توجو سره واورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12438, 'Job 23:7', 'Job', 23, 7, '&nbsp;يو نېک سړے د هغۀ سره د خبرو کولو حق لرى، او زما قاضى خُدائ پاک به مې د تل دپاره بې‌ګناه وګرځوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12439, 'Job 23:8', 'Job', 23, 8, '&nbsp;ګوره چې زۀ مخکښې ورشم نو هلته هم نۀ وى او کۀ شاته لاړ شم نو هلته هم نۀ وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12440, 'Job 23:9', 'Job', 23, 9, '&nbsp;نۀ يې په ښى طرف موندے شم او نۀ يې په ګس طرف موندے شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12441, 'Job 23:10', 'Job', 23, 10, '&nbsp;خو هغۀ ته د هغې لارې پته ده چې کومه ما اختيار کړې ده، او کله چې هغه ما وآزمائى نو زۀ به د سرو زرو په شان صفا يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12442, 'Job 23:11', 'Job', 23, 11, '&nbsp;زۀ د هغۀ په نقشِ قدم روان وم، او زۀ هيڅکله د هغۀ د لارې نه نۀ يم اوړېدلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12443, 'Job 23:12', 'Job', 23, 12, '&nbsp;زۀ تل د هغۀ په حُکمونو عمل کوم، ما د هغۀ کلام د خپل ضرورى خوراک نه هم زيات قيمتى ګڼلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12444, 'Job 23:13', 'Job', 23, 13, '&nbsp;خو هغه بدلېدونکے نۀ دے، نو د هغۀ فېصله څوک بدلولے شى؟ چې د هغۀ څۀ رضا وى نو هم هغه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12445, 'Job 23:14', 'Job', 23, 14, '&nbsp;هغه چې زما دپاره کومه منصوبه لرى نو هغه به پوره کوى، او هغه زما دپاره ډيرې منصوبې لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12446, 'Job 23:15', 'Job', 23, 15, '&nbsp;نو په دې وجه زۀ د هغۀ په حضور کښې يرېږم، کله چې زۀ په دې سوچ کوم نو په يره کښې راګېر شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12447, 'Job 23:16', 'Job', 23, 16, '&nbsp;خُدائ پاک زۀ بې‌زړۀ کړے يم، او قادر خُدائ زۀ يرولے يم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12448, 'Job 23:17', 'Job', 23, 17, '&nbsp;خو زۀ په تيارۀ کښې راګېر يم، او تکه توره تيارۀ زما نه راتاو ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12449, 'Job 24:1', 'Job', 24, 1, '&nbsp;قادر خُدائ د عدالت دپاره وخت ولې نۀ مقرروى؟ او د خُدائ پاک منونکى دا ولې نۀ ګورى چې هغه د ګناهګارانو عدالت کوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12450, 'Job 24:2', 'Job', 24, 2, '&nbsp;بدعمله کسان د حد د پولې کاڼى لرې کوى، هغوئ څاروى پټ کړى او د خپلو رَمو سره يې څروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12451, 'Job 24:3', 'Job', 24, 3, '&nbsp;هغوئ د يتيم خر بوځى، او هغوئ د کونډې غوَيے په ضمانت کښې بوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12452, 'Job 24:4', 'Job', 24, 4, '&nbsp;هغوئ ضرورتمند د سړک نه ديکه کوى، او غريبانان دې ته مجبوروى چې ځان پټ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12453, 'Job 24:5', 'Job', 24, 5, '&nbsp;غريبانان لکه د ځنګلى خرونو په شان په صحرا کښې خوراک لټوى، هغوئ د خپلو بچو دپاره په بل ځائ کښې خوراک نۀ شى پېدا کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12454, 'Job 24:6', 'Job', 24, 6, '&nbsp;هغوئ پردے پټے رېبى او هغوئ د بدعمله خلقو د انګورو په باغونو کښې پاتې شوى انګور راټولوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12455, 'Job 24:7', 'Job', 24, 7, '&nbsp;په يخنۍ کښې هغوئ ټوله شپه بربنډ پراتۀ وى، او په ځان اچولو دپاره ورسره هيڅ هم نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12456, 'Job 24:8', 'Job', 24, 8, '&nbsp;هغوئ په غرونو کښې په بارانونو سره لامدۀ وى، او په کاڼو کښې پناه اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12457, 'Job 24:9', 'Job', 24, 9, '&nbsp;بدعمله خلق د کونډې ماشوم د تى نه په زور لرې کوى، او د غريب ماشوم په ضمانت کښې يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12458, 'Job 24:10', 'Job', 24, 10, '&nbsp;غريبانان د جامو نه بغېر بربنډ ګرځى، او په نهَرو کولمو د خلقو رېبلے شوى ګېډى اوړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12459, 'Job 24:11', 'Job', 24, 11, '&nbsp;د زيتُونو د ونو نه تېل وباسى خو د څَکلو اجازت ورته نۀ وى، هغوئ انګور نچوړوى خو په خپله تږى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12460, 'Job 24:12', 'Job', 24, 12, '&nbsp;چې څوک مرى د هغوئ فريادونه په ښار کښې اورېدے شى، او مالدار خلق چې غريبانانو سره کوم ظلم زياتے کوى نو خُدائ پاک ورته هيڅ توجو نۀ ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12461, 'Job 24:13', 'Job', 24, 13, '&nbsp;هلته هغه څوک دى کوم چې د رڼا خِلاف بغاوت کوى، او هغوئ د دې روښانه لارې نه خبر نۀ دى نو ځکه هغوئ بې‌لارې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12462, 'Job 24:14', 'Job', 24, 14, '&nbsp;قاتِل سحر وختى راپاڅى چې غريب او ضرورتمند ووژنى، او په تيارۀ کښې غلا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12463, 'Job 24:15', 'Job', 24, 15, '&nbsp;زناکار هم د تيارې په اِنتظار کښې وى، خيال يې دا وى چې د هيچا به په ما باندې نظر نۀ وى، او هغه مخ پټوى چې څوک مې ونۀ پېژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12464, 'Job 24:16', 'Job', 24, 16, '&nbsp;د شپې په وخت کښې غلۀ د کورونو کنډرې کوى، او د ورځې خوبونه کوى، او رڼا ته نۀ راوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12465, 'Job 24:17', 'Job', 24, 17, '&nbsp;ځکه چې توره شپه د هغوئ دپاره سحر دے، او هغوئ د تورې تيارې د يرې سره عادت دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12466, 'Job 24:18', 'Job', 24, 18, '&nbsp;هغوئ د اوبو په سر د زګ په شان فانى وى، د هغوئ په زمکه لعنت وئيلے شوے دے نو په دې وجه خلق د انګورو باغونو ته نۀ ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12467, 'Job 24:19', 'Job', 24, 19, '&nbsp;قبر ګناه ګار داسې غېبوى لکه چې اوچ کالى او ګرمى واوره غېبوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12468, 'Job 24:20', 'Job', 24, 20, '&nbsp;د هغوئ خپله مور به هغوئ هېر کړى، او چينجو ته به هغوئ خواږۀ ښکاره شى، او نور به څوک هغوئ نۀ يادوى، نو بدعمله خلق داسې راپرېوځى لکه چې په طوفان کښې ونه راپرېوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12469, 'Job 24:21', 'Job', 24, 21, '&nbsp;هغوئ د بې‌اولاده مور سره ټګى کوى، او د کونډې سره ښۀ نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12470, 'Job 24:22', 'Job', 24, 22, '&nbsp;خو خُدائ پاک طاقتور خلق د خپل قوت سره برباد کړى، کېدے شى چې هغوئ د لږ وخت دپاره کامياب شى خو د هغوئ ژوند څۀ اعتبارى نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12471, 'Job 24:23', 'Job', 24, 23, '&nbsp;کېدے شى چې هغه ورله امن ورکړى چې په حِفاظت سره ژوند تېروى، خو هغوئ د خُدائ پاک د نظر لاندې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12472, 'Job 24:24', 'Job', 24, 24, '&nbsp;د لږ وخت دپاره بدعمله مالداره وى، خو هغوئ بيا د واښو په شان اوچ شى، هغوئ د فصل د سرونو په شان پرې کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12473, 'Job 24:25', 'Job', 24, 25, '&nbsp;کۀ داسې نۀ وى نو څوک به ما دروغژن ثابت کړى، او چې ښکاره کړى چې زۀ څۀ وايم نو هغه تشې خبرې دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12474, 'Job 25:1', 'Job', 25, 1, '&nbsp;بيا شوحى بِلداد جواب ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12475, 'Job 25:2', 'Job', 25, 2, '&nbsp;”اختيار او يره د خُدائ پاک سره دى، هغه په آسمانى بادشاهۍ کښې امن قائموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12476, 'Job 25:3', 'Job', 25, 3, '&nbsp;د هغۀ آسمانى لښکر څوک شمارلے شى؟ د هغۀ رڼا په چا باندې نۀ ځليږى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12477, 'Job 25:4', 'Job', 25, 4, '&nbsp;نو بنى آدم د خُدائ پاک په مخکښې څنګه صادق کېدے شى؟ څوک چې د مور نه پېدا شوے وى نو هغه کس څنګه صفا کېدے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12478, 'Job 25:5', 'Job', 25, 5, '&nbsp;ګوره، د هغۀ په وړاندې ځلېدونکى سپوږمۍ او ستورى هيڅ هم نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12479, 'Job 25:6', 'Job', 25, 6, '&nbsp;نو بيا انسان څۀ څيز دے يو مېږے کۀ يا يو چينجے؟ د خُدائ پاک په نظر کښې د يو انسان څۀ اهميت دے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12480, 'Job 26:1', 'Job', 26, 1, '&nbsp;بيا ايُوب جواب ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12481, 'Job 26:2', 'Job', 26, 2, '&nbsp;”تا د هغه چا مدد څنګه وکړو چې هيڅ طاقت يې نۀ وو. تا هغه کس څنګه بچ کړو چې هيڅ زور يې نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12482, 'Job 26:3', 'Job', 26, 3, '&nbsp;تا يو کم عقل کس له څنګه مشوره ورکړه، او نصيحت دې ورته وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12483, 'Job 26:4', 'Job', 26, 4, '&nbsp;ستا څۀ خيال دے چې څوک به ستا خبرې اورى، او تا ته دا خبرې چا ښودلى دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12484, 'Job 26:5', 'Job', 26, 5, '&nbsp;”د زمکې لاندې په اوبو کښې د مړو روحونه لړزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12485, 'Job 26:6', 'Job', 26, 6, '&nbsp;د مړو دُنيا خُدائ پاک ته ښکاره ده، او د تباهۍ ځائ پټ نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12486, 'Job 26:7', 'Job', 26, 7, '&nbsp;خُدائ پاک آسمان خور کړے دے، او زمکه يې بغېر د څۀ څيز نه راځوړنده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12487, 'Job 26:8', 'Job', 26, 8, '&nbsp;هغه اوبۀ په خپله ټينګه وريځ کښې راغونډوى، او وريځ د دروند والى په وجه نۀ شليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12488, 'Job 26:9', 'Job', 26, 9, '&nbsp;هغه د سپوږمۍ مخ پټوى، او په دې باندې د هغۀ وريځې خوَرې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12489, 'Job 26:10', 'Job', 26, 10, '&nbsp;هغۀ د اوبو دپاسه د آسمان لمن جوړه کړه، هغۀ د رڼا او تيارې په مينځ کښې حد مقرر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12490, 'Job 26:11', 'Job', 26, 11, '&nbsp;د آسمان بنيادونه ولړزيږى، او دا د هغۀ په رټنه باندې ودرزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12491, 'Job 26:12', 'Job', 26, 12, '&nbsp;د خپل طاقت په ذريعه هغۀ سمندر قلار کړو، او د خپلې پوهې په ذريعه يې سمندرى بلا تباه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12492, 'Job 26:13', 'Job', 26, 13, '&nbsp;د هغۀ د ساه په ذريعه آسمان ښائسته شو، او د هغۀ لاس تښتېدونکې بلا وشلوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12493, 'Job 26:14', 'Job', 26, 14, '&nbsp;دا د هغۀ د طاقت معمولى کارنامې دى، دا د يو معمولى آواز په شان دے چې مونږ اورېدلے وى. خو داسې څوک شته چې ورته د هغۀ د دروند آواز د زور پته لګى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12494, 'Job 27:1', 'Job', 27, 1, '&nbsp;ايُوب خپله خبره جارى وساتله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12495, 'Job 27:2', 'Job', 27, 2, '&nbsp;”زۀ په ژوندى خُدائ پاک قسم خورم، چا چې زما حقُونه اخستى دى، او هغه قادر خُدائ چا چې زما ژوند تريخ کړے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12496, 'Job 27:3', 'Job', 27, 3, '&nbsp;چې ترڅو پورې زۀ ژوندے يم او چې د خُدائ پاک روح په ما کښې وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12497, 'Job 27:4', 'Job', 27, 4, '&nbsp;نو زما ژبه به غلطې خبرې ونۀ کړى، او زما ژبه به دروغ ونۀ وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12498, 'Job 27:5', 'Job', 27, 5, '&nbsp;زۀ به هيڅکله دا ونۀ وايم چې تۀ په حقه يې، ترڅو پورې چې مړ شوے نۀ يم نو صداقت به ما کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12499, 'Job 27:6', 'Job', 27, 6, '&nbsp;زۀ به دا دعوىٰ هيڅکله پرې نۀ ږدم چې زۀ بې‌ګناه يم، ځکه چې ټول عُمر زما ضمير صفا دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12500, 'Job 27:7', 'Job', 27, 7, '&nbsp;څوک چې زما مخالفت کوى يا ما سره جګړې کوى نو هغوئ ته دې د ګناهګارو او بدعملو په شان سزا مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');